        LazyValues = (value.LazyValues |> Set.map (fun x -> nodeId x))
        DefinitionOnlyThunks = (value.DefinitionOnlyThunks |> Set.map (fun x -> nodeId x))
        LazyPrograms = (value.LazyPrograms |> Map.toSeq |> Seq.map (fun (k, v) -> nodeId k, mapLazyProgramWitness v) |> Map.ofSeq)
        Sequences = (value.Sequences |> Map.toSeq |> Seq.map (fun (k, v) -> nodeId k, mapSequenceWitnessContract v) |> Map.ofSeq)
        SequenceCopies = (value.SequenceCopies |> Map.toSeq |> Seq.map (fun (k, v) -> nodeId k, mapSequenceTemplateCopy v) |> Map.ofSeq)
        SequencePrograms = (value.SequencePrograms |> Map.toSeq |> Seq.map (fun (k, v) -> nodeId k, mapSequenceProgramWitness v) |> Map.ofSeq)
        Startup = (value.Startup |> Option.map (fun x -> mapStartupWitness x))
        SlotAuthorities = (value.SlotAuthorities |> Set.map (fun x -> nodeId x))
        Requirements = (value.Requirements |> Map.toSeq |> Seq.map (fun (k, v) -> nodeId k, mapRequirementWitness v) |> Map.ofSeq)
        PatternRequirements = (value.PatternRequirements |> Map.toSeq |> Seq.map (fun (k, v) -> nodeId k, nodeId v) |> Map.ofSeq)
        ProgramStorage = mapProgramStorageInventory value.ProgramStorage
        LiteralPoolAnchors = value.LiteralPoolAnchors
    } : Fidelity.PSG.StorageWitnessProjection)

and mapSubstrateKind (value: N.SubstrateKind) : Fidelity.PSG.SubstrateKind =
    match value with
    | N.SubstrateKind.CPU -> Fidelity.PSG.SubstrateKind.CPU
    | N.SubstrateKind.GPU -> Fidelity.PSG.SubstrateKind.GPU
    | N.SubstrateKind.NPU -> Fidelity.PSG.SubstrateKind.NPU
    | N.SubstrateKind.FPGA -> Fidelity.PSG.SubstrateKind.FPGA

and mapTypeDefKind (value: S.TypeDefKind) : Fidelity.PSG.TypeDefKind =
    match value with
    | S.TypeDefKind.RecordDef(a0) -> Fidelity.PSG.TypeDefKind.RecordDef((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, freeze t1)))))
    | S.TypeDefKind.UnionDef(a0) -> Fidelity.PSG.TypeDefKind.UnionDef((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, (t1 |> List.map (fun x -> (let (t0, t1) = x in (t0, freeze t1)))))))))
    | S.TypeDefKind.ClassDef -> Fidelity.PSG.TypeDefKind.ClassDef
    | S.TypeDefKind.InterfaceDef -> Fidelity.PSG.TypeDefKind.InterfaceDef
    | S.TypeDefKind.StructDef -> Fidelity.PSG.TypeDefKind.StructDef
    | S.TypeDefKind.EnumDef(a0) -> Fidelity.PSG.TypeDefKind.EnumDef((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapNativeLiteral t1)))))
    | S.TypeDefKind.AbbreviationDef(a0) -> Fidelity.PSG.TypeDefKind.AbbreviationDef(freeze a0)

and mapTypeIdentity (value: N.TypeIdentity) : Fidelity.PSG.TypeIdentity =
    match value with
    | N.TypeIdentity.Application(a0, a1) -> Fidelity.PSG.TypeIdentity.Application(mapConstructorIdentity a0, (a1 |> List.map (fun x -> mapTypeIdentity x)))
    | N.TypeIdentity.Numeric(a0, a1) -> Fidelity.PSG.TypeIdentity.Numeric(mapCarrierIdentity a0, mapDimension a1)
    | N.TypeIdentity.Measure(a0) -> Fidelity.PSG.TypeIdentity.Measure(mapDimension a0)
    | N.TypeIdentity.Variable(a0, a1) -> Fidelity.PSG.TypeIdentity.Variable(a0, mapTypeParamKind a1)
    | N.TypeIdentity.Function(a0, a1) -> Fidelity.PSG.TypeIdentity.Function(mapTypeIdentity a0, mapTypeIdentity a1)
    | N.TypeIdentity.Tuple(a0, a1) -> Fidelity.PSG.TypeIdentity.Tuple(a0, (a1 |> List.map (fun x -> mapTypeIdentity x)))
    | N.TypeIdentity.AnonymousRecord(a0, a1) -> Fidelity.PSG.TypeIdentity.AnonymousRecord(a0, (a1 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapTypeIdentity t1)))))
    | N.TypeIdentity.Union(a0, a1) -> Fidelity.PSG.TypeIdentity.Union(mapConstructorIdentity a0, (a1 |> List.map (fun x -> (let (t0, t1, t2) = x in (t0, t1, (t2 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapTypeIdentity t1)))))))))
    | N.TypeIdentity.Forall(a0, a1) -> Fidelity.PSG.TypeIdentity.Forall((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapTypeParamKind t1)))), mapTypeIdentity a1)
    | N.TypeIdentity.Byref(a0, a1) -> Fidelity.PSG.TypeIdentity.Byref(mapByrefKind a0, mapTypeIdentity a1)
    | N.TypeIdentity.NativePointer(a0) -> Fidelity.PSG.TypeIdentity.NativePointer(mapTypeIdentity a0)
    | N.TypeIdentity.Lazy(a0) -> Fidelity.PSG.TypeIdentity.Lazy(mapTypeIdentity a0)
    | N.TypeIdentity.Sequence(a0) -> Fidelity.PSG.TypeIdentity.Sequence(mapTypeIdentity a0)
    | N.TypeIdentity.Enumerator(a0) -> Fidelity.PSG.TypeIdentity.Enumerator(mapTypeIdentity a0)
    | N.TypeIdentity.List(a0) -> Fidelity.PSG.TypeIdentity.List(mapTypeIdentity a0)
    | N.TypeIdentity.Map(a0, a1) -> Fidelity.PSG.TypeIdentity.Map(mapTypeIdentity a0, mapTypeIdentity a1)
    | N.TypeIdentity.Set(a0) -> Fidelity.PSG.TypeIdentity.Set(mapTypeIdentity a0)
    | N.TypeIdentity.Error(a0) -> Fidelity.PSG.TypeIdentity.Error(a0)

and mapTypeParamKind (value: N.TypeParamKind) : Fidelity.PSG.TypeParamKind =
    match value with
    | N.TypeParamKind.Type -> Fidelity.PSG.TypeParamKind.Type
    | N.TypeParamKind.Measure -> Fidelity.PSG.TypeParamKind.Measure
    | N.TypeParamKind.Carrier -> Fidelity.PSG.TypeParamKind.Carrier

and mapValueRange (value: N.ValueRange) : Fidelity.PSG.ValueRange =
    match value with
    | N.ValueRange.Empty -> Fidelity.PSG.ValueRange.Empty
    | N.ValueRange.Bounded(a0, a1) -> Fidelity.PSG.ValueRange.Bounded(a0, a1)
    | N.ValueRange.Above(a0) -> Fidelity.PSG.ValueRange.Above(a0)
    | N.ValueRange.Below(a0) -> Fidelity.PSG.ValueRange.Below(a0)
    | N.ValueRange.Unbounded -> Fidelity.PSG.ValueRange.Unbounded

and mapValueRepresentation (value: S.ValueRepresentation) : Fidelity.PSG.ValueRepresentation =
    match value with
    | S.ValueRepresentation.Scalar(a0) -> Fidelity.PSG.ValueRepresentation.Scalar(mapSettledSlot a0)
    | S.ValueRepresentation.Buffer(a0, a1) -> Fidelity.PSG.ValueRepresentation.Buffer(a0, mapValueRepresentation a1)
    | S.ValueRepresentation.Record(a0, a1) -> Fidelity.PSG.ValueRepresentation.Record((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapValueRepresentation t1)))), a1)
    | S.ValueRepresentation.Tag(a0) -> Fidelity.PSG.ValueRepresentation.Tag(a0)

and mapWidthDimension (value: N.WidthDimension) : Fidelity.PSG.WidthDimension =
    match value with
    | N.WidthDimension.Pointer -> Fidelity.PSG.WidthDimension.Pointer
    | N.WidthDimension.Register -> Fidelity.PSG.WidthDimension.Register

and mapWitnessEmissionProjection (value: S.WitnessEmissionProjection) : Fidelity.PSG.WitnessEmissionProjection =
    ({
        Ordinary = mapOrdinaryDemandProjection value.Ordinary
        Callable = mapCallableEmissionProjection value.Callable
        Storage = mapStorageWitnessProjection value.Storage
        Boundary = mapBoundaryEmissionProjection value.Boundary
        Numeric = mapNumericWitnessProjection value.Numeric
        Memory = mapMemoryWitnessProjection value.Memory
        Spatial = mapSpatialModuleProjection value.Spatial
    } : Fidelity.PSG.WitnessEmissionProjection)

/// A checker type crosses as its identity, with the current substitution applied.
and freeze (value: N.NativeType) : Fidelity.PSG.TypeIdentity =
    mapTypeIdentity (Clef.Compiler.NativeTypedTree.TypeIdentities.ofType value)
